templates.react:
export function VisualHierarchy({
  strong = {{strong}},
  heading = "{{heading}}",
  body = "{{body}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 18, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", color: "#241430" }}>
      <h3 style={{ margin: "0 0 6px", color: accent, fontSize: strong ? 22 : 15, fontWeight: strong ? 800 : 500 }}>{heading}</h3>
      <p style={{ margin: "0 0 14px", fontSize: strong ? 13 : 14, color: strong ? "#241430aa" : "#241430" }}>{body}</p>
      <button type="button" style={{ display: "block", fontSize: 14, fontWeight: strong ? 700 : 500, color: "#fff", background: accent, border: "none", borderRadius: 6, padding: "8px 14px", cursor: "pointer", opacity: strong ? 1 : .85, boxShadow: strong ? "0 4px 10px rgba(36,20,48,.25)" : "none" }}>View report</button>
      <p style={{ margin: "14px 0 0", fontSize: 11, color: "#241430aa" }}>{strong ? "Strong" : "Flat"} hierarchy &mdash; same content, different emphasis</p>
    </div>
  );
}
